})();

Example

(function greet() {

  let text = "Hello! I called myself.";

})();

greet(); // ⛔ ReferenceError

Example

(function factorial(n) {

  if (n <= 1) return 1;

  return n * factorial(n - 1); // recursive call

})(5);

const counter = (function () {

