sections.content:
Sometimes you want to add new properties (or methods) to all existing objects of a given type.

Sometimes you want to add new properties (or methods) to an object 
constructor.

Previously you have learned learned how to use an object constructor:

Example

function Person(first, last, age, eyecolor) {

this.firstName = first;

  this.lastName = last;

this.age = age;

this.eyeColor = eyecolor;

}

const myFather = new Person("John", "Doe", 50, "blue");

const myMother = new Person("Sally", "Rally", 48, "green");

Try it Yourself »

You cannot add a new property to an existing object constructor:

Example

 Person.nationality = "English";

Try it Yourself »

To add a new property to a constructor, you must add it to the 
constructor function:

Example

function Person(first, last, age, eyecolor) {

this.firstName = first;

this.lastName = last;

this.age = age;

this.eyeColor = eyecolor;
  this.nationality = "English";

}

Try it Yourself »

The JavaScript prototype property allows you to add new properties to object 
constructors:

Example

function Person(first, last, age, eyecolor) {

   this.firstName = first;

   this.lastName = last;

   this.age = age;

   this.eyeColor = eyecolor;

}

 Person.prototype.nationality = "English";

Try it Yourself »

The JavaScript prototype property also allows you to add new methods to object 
constructors:

Example

function Person(first, last, age, eyecolor) {

   this.firstName = first;

   this.lastName = last;

   this.age = age;

  this.eyeColor = eyecolor;

}

 Person.prototype.name = function() {

   return this.firstName + " " + this.lastName;

};

