  }

}

class Car {

  constructor(name, year) {

    this.name = name;

    this.year = year;

  }
  age() {

    const date = new Date();

    return date.getFullYear() - this.year;

  }
}

const myCar = new Car("Ford", 2014);

document.getElementById("demo").innerHTML =

"My car is " + myCar.age() + " years old.";

sections.content:
Use the keyword class to create a class.

Always add a method named constructor():

Syntax

class ClassName {

  constructor() { ... }

}

Example

class Car {

  constructor(name, year) {

    this.name = name;

    this.year = year;

  }

}

The example above creates a class named "Car".

The class has two initial properties: "name" and "year".

A JavaScript class is not an object.

It is a template for JavaScript objects.

Class methods are created with the same syntax as object methods.

Use the keyword class to create a class.

Always add a constructor() method.

Then add any number of methods.

Syntax

class ClassName {

  constructor() { ... }

  method_1() { ... }

  method_2() { ... }

  method_3() { ... }

}

Create a Class method named "age", that returns the Car age:

Example

class Car {

  constructor(name, year) {

    this.name = name;

    this.year = year;

  }
  age() {

    const date = new Date();

    return date.getFullYear() - this.year;

  }
}

const myCar = new Car("Ford", 2014);

document.getElementById("demo").innerHTML =

"My car is " + myCar.age() + " years old.";

Try it Yourself »

You can send parameters to Class methods:

Example

class Car {
  constructor(name, year) {

 this.name = name;
    this.year = year;
  }

 age(x) {
    return x - this.year;
  }
}

 const date = new Date();

 let year = date.getFullYear();

const myCar = new 
 Car("Ford", 2014);
document.getElementById("demo").innerHTML=
"My car is 
 " + myCar.age(year) + " years old."; 

Try it Yourself »

Classes syntax must be written following The "use strict" Directive.

You will get an 
error if you do not follow the "strict mode" rules.

Example
In "strict mode" you will get an error if you use a variable without 
declaring it:

class Car {

  constructor(name, year) {

    this.name = name;

    this.year = year;

  }
  age() {

    // date = new Date();  // This will not work

    const date = new Date(); // This will work

    return date.getFullYear() - this.year;

  }
}

Try it Yourself »

